50	function format_price($cents, $currency = 'CZK')
51	{
52	    $amount = ((int) $cents) / 100;
53	    $s = number_format($amount, 2, ',', ' ');
54	    switch ($currency) {
55	        case 'CZK':
56	            return $s . ' Kč';
57	        case 'EUR':
58	            return $s . ' €';
59	        case 'USD':
60	            return '$' . $s;
